const armed = String(msg.payload).trim().toUpperCase() === 'ON';
flow.set('armedAway', armed);
node.status({fill: armed ? 'red' : 'green', shape: 'dot', text: armed ? 'ARMED AWAY' : 'disarmed'});
return null;

const presence = String(msg.payload).trim().toLowerCase();
flow.set('natePresence', presence);
const known = presence === 'home' || presence === 'not_home';
node.status({fill: known ? (presence === 'home' ? 'green' : 'yellow') : 'grey', shape: 'dot', text: presence || 'unknown'});
return null;

let payload = msg.payload;
if (typeof payload === 'string') {
    try { payload = JSON.parse(payload); } catch (error) { return null; }
}
if (typeof payload?.contact !== 'boolean') return null;
const stateKey = `contact:${msg.topic}`;
const previous = flow.get(stateKey);
flow.set(stateKey, payload.contact);
// Never alarm from the first observation after startup or deploy.
if (previous === undefined) {
    node.status({fill:'grey', shape:'ring', text:`initialized ${payload.contact ? 'closed' : 'open'}`});
    return null;
}
if (previous === true && payload.contact === false) {
    msg.door = msg.topic.endsWith('door_front_contact') ? 'front' : 'second';
    msg.detectedAt = new Date().toISOString();
    msg.originalPayload = payload;
    node.status({fill:'yellow', shape:'dot', text:`${msg.door} opened`});
    return msg;
}
return null;

const armed = flow.get('armedAway') === true;
const presence = String(flow.get('natePresence') || 'unknown').toLowerCase();
const now = Date.now();
const lastAlarmAt = Number(flow.get('lastAlarmAt') || 0);
let decision = 'blocked';
let reason = '';
if (!armed) reason = 'system disarmed';
else if (presence === 'home') reason = 'Nate is home';
else if (presence !== 'not_home') reason = 'presence unknown — fail safe';
else if (now - lastAlarmAt < 10 * 60 * 1000) reason = '10 minute cooldown active';
else {
    decision = 'alarm_candidate';
    reason = 'armed and Nate is away';
    flow.set('lastAlarmAt', now);
}
const audit = {
    topic: 'cabin/security/intrusion/event',
    payload: JSON.stringify({decision, reason, door:msg.door, detectedAt:msg.detectedAt, evaluatedAt:new Date().toISOString(), armedAway:armed, natePresence:presence, liveSirensEnabled:false}),
    qos: 1, retain: false
};
node.status({fill: decision === 'alarm_candidate' ? 'red' : 'green', shape:'dot', text:reason});
return [decision === 'alarm_candidate' ? msg : null, audit];
